values ('dialog_fq_conc_089', 'fq_conc_089', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Beneath the Siphon Core lies the World Engine", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Collect 3x Materials; Defeat 2x Gigantic Jotunn\n\nComplete and report back.\n\nRewards: 11000 EXP · 5500 Currency · 2750 CRD · 3500 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 119)
