values ('dialog_fq_conc_091', 'fq_conc_091', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. The Jotunn Purge — With the World Engine stabilizing Xylos, remaining hostile entities are bei...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 5x Gigantic Jotunn; Defeat 8x Aethel Iron Carapace\n\nComplete and report back.\n\nRewards: 10000 EXP · 5000 Currency · 2500 CRD · 3200 Reputation · Stabilizer Gyro Unit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 121)
