values ('dialog_fq_arc_024', 'fq_arc_024', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Scholar! The Observatory has been recording unusual patterns. A Sunken Aethel Leviathan has been detected in the peak''s subterranean lake", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Your previous encounters generated extraordinary data. The resonance patterns suggest a deeper structure — a language waiting to be decoded.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Sunken Aethel Leviathan; Collect 3x leviathan_scale\n\nBring back everything you can. The archives await.\n\nRewards: 850 EXP · 460 Currency · 230 CRD · 480 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 154)
