values ('dialog_fq_arc_027', 'fq_arc_027', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. The Aethel Storm Belt is a contested zone of intense electromagnetic activity", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard isn''t just a power source — it''s a fragment of Aethelgardian consciousness, a library encoded in energy. Every creature affected carries a piece. We collect them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to AETHEL_STORM_BELT; Collect 2x desert_chitin\n\nBring back everything you can. The archives await.\n\nRewards: 700 EXP · 400 Currency · 400 Reputation · Con Nutrient Ration", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 157)
