values ('dialog_fq_iron_047', 'fq_iron_047', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. Chrono Elimination — Chrono Wraiths warp time around Hegemony positions", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 2x Chrono Wraith; Collect 1x Develop temporal countermeasure data.\n\nStrength prevails.\n\nRewards: 3500 EXP · 1800 Currency · 900 CRD · 1100 Reputation · Quantum Distortion Stone", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 277)
