values ('dialog_fq_iron_086', 'fq_iron_086', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. Apex Titan Fall — The Gravity Titan manifests once more", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 1x Gravity Titan; Collect 1x Confirm Titan fall.\n\nStrength prevails.\n\nRewards: 14000 EXP · 7000 Currency · 3500 CRD · 4500 Reputation · Titan Core + Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 316)
