values ('dialog_fq_iron_089', 'fq_iron_089', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. World Engine Subjugation — The World Engine can reshape Xylos", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium thinks diplomacy solves everything. The Arcanum thinks reading books does. We know better. Strength is the only language this world understands.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Collect 3x Obtain Engine control codes.; Defeat 2x Gigantic Jotunn\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 11000 EXP · 5500 Currency · 2750 CRD · 3500 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 319)
