values ('dialog_fq_merid_040', 'fq_merid_040', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Come in. Business has been good — but it could be better. The Senior Partner trial", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Port Meridian handles more cargo in a day than the Concordium''s entire logistics division. When something threatens that, we don''t write reports — we pay people to remove threats.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 1x Ashen Drake; Defeat 1x Aethel Behemoth; Defeat 1x Sunken Aethel Leviathan\n\nSimple. Profitable. Done.\n\nRewards: 5000 EXP · 2500 Currency · 2000 Reputation · Drake Heart + Ancient Scale", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 370)
