values ('dialog_fq_merid_074', 'fq_merid_074', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Associate! Just who I wanted to see. Competitor Purge — Abyssal forces are attempting to steal Forge monopoly", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Other factions fight over principles. Principles don''t pay for ship repairs. The Cartel pays in hard currency — always has, always will.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Here''s the deal: Defeat 8x Aethel Abyssal Reaver; Defeat 5x Aethel Void Channeler\n\nSimple. Profitable. Done.\n\nRewards: 6800 EXP · 3400 Currency · 1700 CRD · 2300 Reputation · Aethel Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 404)
