values ('dialog_fq_omni_030', 'fq_omni_030', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Asset, your metrics have been reviewed. Firmware Update — System analysis indicates Ascension-ready status", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Speak with npc_omnicorp_class_trainer; Defeat 1x Resonance Echo; Defeat 1x Titan Proto Core\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 2500 EXP · 1200 Currency · 800 Reputation · Con Elite Recovery Pack + Astral Phase Crystal Pure", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 458)
