values ('dialog_fq_omni_064', 'fq_omni_064', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. Gigantic Jotunns refuse to vacate anchor deployment sites", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Gigantic Jotunn; Collect 3x Confirm all anchors deployed.\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 6500 EXP · 3300 Currency · 1650 CRD · 2100 Reputation · Titan Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 492)
