values ('dialog_fq_omni_078', 'fq_omni_078', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "OmniCorp''s projections indicate a resource gap requiring intervention. Titan Proto Cores are failed products", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The other factions play politics. OmniCorp plays percentages. We''ve identified a gap impacting quarterly projections. You''re the asset closing that gap.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 2x Titan Proto Core; Collect 1x Report recycling yield.\n\nReport completion via standard channels.\n\nRewards: 9000 EXP · 4500 Currency · 2250 CRD · 2800 Reputation · Titan Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 506)
