values ('dialog_fq_omni_094', 'fq_omni_094', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. Final Forge production cycle", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Defeat 8x Aethel Void Channeler; Defeat 3x Titan Forge Automaton\n\nReport completion via standard channels.\n\nRewards: 11000 EXP · 5500 Currency · 2750 CRD · 3500 Reputation · Raw Aethel Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 522)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_omni_095', 'fq_omni_095', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "OmniCorp''s projections indicate a resource gap requiring intervention. The Cradle Expanse is now Omnicorp-managed territory", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 10x Aethel Rift Stalker; Defeat 1x Gravity Titan\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 13000 EXP · 6500 Currency · 3250 CRD · 4200 Reputation · Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 523)
