values ('dialog_fq_omni_097', 'fq_omni_097', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "OmniCorp''s projections indicate a resource gap requiring intervention. Execute final system backup before singularity", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "OmniCorp doesn''t waste resources on sentiment. Every operation is calculated for maximum return. This one is flagged high-yield — your compensation reflects that.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Gigantic Jotunn; Defeat 1x Abyss Harbinger; Collect 1x Confirm backup complete.\n\nCompletion: immediate. Compensation: per contract.\n\nRewards: 15000 EXP · 7500 Currency · 3750 CRD · 5000 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 525)
