values ('dialog_fq_omni_099', 'fq_omni_099', 'npc_director_vey', 'greeting', '[{"id": "greeting", "text": "Cleared for your next assignment. The deepest Void Echo Chasm", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Every credit invested in you has returned positive value. That is a data point, not a compliment. Based on that data, we''re increasing your operational scope.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Tasking: Travel to VOID_ECHO_CHASM; Defeat 1x Gravity Titan; Defeat 1x Abyss Harbinger (+1 more)\n\nReport completion via standard channels.\n\nRewards: 25000 EXP · 12000 Currency · 6000 CRD · 8000 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 527)
