values ('dialog_fq_shard_005', 'fq_shard_005', 'npc_shard_class_trainer', 'greeting', '[{"id": "greeting", "text": "Come, Child of the Shard. The Shard Has Heard You — Oracle Seraphel", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard is not a weapon — it is a living memory of everything before the Severance. Billions of souls, a civilization, compressed into fragments. Shard-touched creatures are echoes.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Speak with npc_shard_class_trainer; Speak with class_change_screen; Defeat 3x Glowvine Sprite\n\nWalk in the Shard''s light.\n\nRewards: 400 EXP · 200 Currency · 150 Reputation · Wpn Apprentice Staff + Armor Cloth Robes", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 533)
