values ('dialog_fq_shard_026', 'fq_shard_026', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Come, Child of the Shard. The Shard Speaks in Lightning — The Aethel Storm Belt is where the Children of the Shard have always sent t...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Glowvine Forest sang before the Concordium''s first wall, before the Hegemony''s first weapon. Listen to its song — it guides where weapons and ledgers cannot.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to AETHEL_STORM_BELT; Collect 2x Materials\n\nThe Shard''s blessing goes with you, Child.\n\nRewards: 1850 EXP · 925 Currency · 575 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 554)
