values ('dialog_fq_shard_081', 'fq_shard_081', 'npc_elder_malakor', 'greeting', '[{"id": "greeting", "text": "Peace be with you, Child. The Glowvine has been restless. The Cradle Expanse''s purification continues", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Glowvine Forest sang before the Concordium''s first wall, before the Hegemony''s first weapon. Listen to its song — it guides where weapons and ledgers cannot.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your path, Child: Defeat 5x Aethel Abyssal Reaver\n\nWalk in the Shard''s light.\n\nRewards: 5000 EXP · 2500 Currency · 1250 CRD · 2000 Reputation", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 609)
