values ('dialog_fq_star_017', 'fq_star_017', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Stand ready. General Kaelen''s requisition from the Warpath''s strategic materials cache r...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Collect 4x rare_emblem; Defeat 3x Warpath Scout\n\nThe code is clear. Execution is mandatory.\n\nRewards: 480 EXP · 260 Currency · 260 Reputation · Memory Fragment Chip", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 645)
