values ('dialog_fq_star_018', 'fq_star_018', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Stand ready. A War Machine Sentinel Commander has activated deep in the Warpath''s archae...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Starforged Legion crossed the void after our homeworld was destroyed. Billions lost. Everything lost. But the code survived. Every mission declares: the Legion endures.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Defeat 1x Resonance Echo; Defeat 2x Warpath Champion\n\nComplete with the honor the code demands.\n\nRewards: 800 EXP · 450 Currency · 225 CRD · 450 Reputation · Entropy Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 646)
