values ('dialog_fq_star_065', 'fq_star_065', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Legionnaire. The Siphon''s Core: The Legion Arrives — The Aethel Siphon Core", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Starforged Legion crossed the void after our homeworld was destroyed. Billions lost. Everything lost. But the code survived. Every mission declares: the Legion endures.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to AETHEL_SIPHON_CORE; Collect 2x Materials\n\nThe code is clear. Execution is mandatory.\n\nRewards: 3800 EXP · 1900 Currency · 918 CRD · 1160 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 693)
