values ('dialog_fq_star_066', 'fq_star_066', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "Stand ready. Abyssal Reavers have colonized the Aethel Siphon Core''s approach corridors", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Starforged Legion crossed the void after our homeworld was destroyed. Billions lost. Everything lost. But the code survived. Every mission declares: the Legion endures.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Defeat 8x Aethel Abyssal Reaver; Defeat 5x Aethel Void Channeler\n\nComplete with the honor the code demands.\n\nRewards: 3850 EXP · 1925 Currency · 930 CRD · 1175 Reputation · Aethel Core Shard", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 694)
