values ('dialog_msq_lv5_class_intro', 'msq_lv5_class_intro', 'npc_class_advisor', 'start', '[{"id": "start", "text": "Your First Calling", "options": [{"text": "Accept Quest", "next": "exit", "action": "accept_quest"}, {"text": "Details...", "next": "details", "action": ""}, {"text": "Not right now.", "next": "exit", "action": "exit"}]}, {"id": "details", "text": "Objectives:\n• Speak with class_trainer\n• Speak with class_change_screen\n\nRewards: 250 EXP · 100 currency · 50 CRD", "options": [{"text": "Accept Quest", "next": "exit", "action": "accept_quest"}, {"text": "Go back.", "next": "start", "action": ""}]}]'::jsonb, 'dialog_quests.json', 729)
